import { mkdir, open, readFile, stat, unlink } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const LOCK_PATH = resolve(dirname(fileURLToPath(import.meta.url)), "..", ".tmp", "app-fixture.lock");
/** 等锁上限：三支串行的实际耗时是秒级；给足余量吸收并发负载，但绝不无限等。 */
const WAIT_TIMEOUT_MS = 5 * 60_000;
const RETRY_MS = 20;

function alive(pid: number): boolean {
  if (!Number.isInteger(pid) || pid <= 0) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

/** 拿锁；返回的函数只释放**自己**那把（锁被判死后别人接管时，不能替新持有者解锁）。 */
export async function acquireAppFixtureLock(): Promise<() => Promise<void>> {
  await mkdir(dirname(LOCK_PATH), { recursive: true });
  const started = Date.now();
  for (;;) {
    try {
      const handle = await open(LOCK_PATH, "wx");
      await handle.writeFile(String(process.pid), "utf8");
      await handle.close();
      let released = false;
      return async () => {
        if (released) return;
        released = true;
        const owner = (await readFile(LOCK_PATH, "utf8").catch(() => "")).trim();
        if (owner !== String(process.pid)) return;
        await unlink(LOCK_PATH).catch(() => undefined);
      };
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== "EEXIST") throw err;
      // 锁里没有 pid（刚建成、还没来得及写）时按「活着」处理：等下一拍再看，别去删。
      // 但空了 60s 还没人写 = 持有者在 open 与 write 之间死了，接管，别让整张表等满 5 分钟。
      const ownerText = (await readFile(LOCK_PATH, "utf8").catch(() => "")).trim();
      const owner = Number.parseInt(ownerText, 10);
      if (!Number.isInteger(owner)) {
        const createdAt = await stat(LOCK_PATH).then((info) => info.mtimeMs).catch(() => 0);
        if (createdAt !== 0 && Date.now() - createdAt > 60_000) {
          await unlink(LOCK_PATH).catch(() => undefined);
          continue;
        }
      } else if (owner !== process.pid && !alive(owner)) {
        await unlink(LOCK_PATH).catch(() => undefined);
        continue;
      }
      if (Date.now() - started > WAIT_TIMEOUT_MS) {
        throw new Error("等 fixtures/todo-app 的跨文件锁超时（" + LOCK_PATH + "）：另一支持锁的判卷没有收尾");
      }
      await new Promise((done) => setTimeout(done, RETRY_MS));
    }
  }
}

// 会话归属与「按会话根串行」的统一入口（指针接入 Task 3）。
//
// 两件事在这里收敛：
//   ① **精确寻址**：两个已登记工作区可能各有一个同名会话；只给 id 时必须唯一才认，歧义就报错
//      （绝不「扫到第一个就继续」——那是把别的项目的日志当真）。
//   ② **根级临界区**：依赖检查与破坏性 mutation（改名/删除/创建指针）必须在同一个锁里完成，
//      否则「检查时没有子会话、检查完又被建了一个」会把父日志改成断链。进程内用 promise 链串行，
//      跨进程（CLI + desktop）用会话根里的 `.session-mutation.lock`（O_EXCL）。锁被活人占着或
//      崩溃遗留时**显式报错并给出锁路径**，不凭超时自动删锁。
import { existsSync } from "node:fs";
import { open, readFile, realpath, rename, rm, unlink, type FileHandle } from "node:fs/promises";
import { join } from "node:path";
import { forkSessionPointer, readSessionView, forkPointInView, type SessionRef } from "../events";
import { isSessionInRoot, workspaceOfSessionsRoot } from "./sessions";

export const SESSION_MUTATION_LOCK = ".session-mutation.lock";

export interface ResolveSessionInput {
  sessionId: string;
  /** 显式工作区（已登记根的规范路径）；缺省时要求 id 在登记根里唯一。 */
  workspace?: string;
}

/** 会话 id → 精确来源。`allowedWorkspaces` 必须是可信注册根（调用方已规范化）。 */
export async function resolveSessionRef(
  input: ResolveSessionInput,
  allowedWorkspaces: readonly string[],
): Promise<SessionRef> {
  if (typeof input.sessionId !== "string" || input.sessionId.length === 0) {
    throw new Error("会话 id 不能是空串");
  }
  const roots: { workspace: string; root: string }[] = [];
  for (const workspace of allowedWorkspaces) {
    const canonical = await realpath(workspace).catch(() => null);
    if (canonical === null) continue;
    roots.push({ workspace: canonical, root: join(canonical, ".agent", "sessions") });
  }
  if (input.workspace !== undefined) {
    const target = await realpath(input.workspace).catch(() => null);
    const hit = target === null ? undefined : roots.find((r) => r.workspace === target);
    if (hit === undefined) throw new Error(`工作区未登记：${input.workspace}`);
    if (!(await isSessionInRoot(hit.root, input.sessionId))) {
      throw new Error(`会话不存在：${input.sessionId} @ ${hit.workspace}`);
    }
    return { workspace: hit.workspace, sessionId: input.sessionId };
  }
  const hits: string[] = [];
  for (const r of roots) if (await isSessionInRoot(r.root, input.sessionId)) hits.push(r.workspace);
  if (hits.length === 0) throw new Error(`会话不存在：${input.sessionId}`);
  if (hits.length > 1) {
    throw new Error(`会话 id 在多个工作区同时存在（${hits.join("、")}），必须显式指定 workspace：${input.sessionId}`);
  }
  return { workspace: hits[0]!, sessionId: input.sessionId };
}

/** 进程内：同一规范会话根上的 mutation 串行（跨进程那一半是文件锁）。 */
const chains = new Map<string, Promise<void>>();
const lockHandles = new Map<string, FileHandle>();

function processAlive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

async function acquireRootLock(root: string): Promise<void> {
  const lockPath = join(root, SESSION_MUTATION_LOCK);
  let handle: FileHandle;
  try {
    handle = await open(lockPath, "wx");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
    const raw = await readFile(lockPath, "utf8").catch(() => "");
    const pid = Number.parseInt(raw.trim(), 10);
    const alive = Number.isSafeInteger(pid) && pid > 0 && processAlive(pid);
    throw new Error(
      alive
        ? `会话根正被另一个进程占用（pid ${String(pid)}）：${lockPath}`
        : `会话根的锁是崩溃遗留的，需人工确认后删除：${lockPath}`,
    );
  }
  lockHandles.set(root, handle);
  await handle.writeFile(`${String(process.pid)}\n`);
}

async function releaseRootLock(root: string): Promise<void> {
  const handle = lockHandles.get(root);
  lockHandles.delete(root);
  if (handle !== undefined) await handle.close().catch(() => undefined);
  await unlink(join(root, SESSION_MUTATION_LOCK)).catch(() => undefined);
}

/** 在会话根的临界区里执行 `operation`：进程内串行 + 跨进程文件锁。 */
export async function withSessionMutation<T>(sessionsRoot: string, operation: () => Promise<T>): Promise<T> {
  const root = await realpath(sessionsRoot);
  const previous = chains.get(root) ?? Promise.resolve();
  let release!: () => void;
  const gate = new Promise<void>((resolveGate) => { release = resolveGate; });
  const tail = previous.then(() => gate);
  chains.set(root, tail);
  await previous.catch(() => undefined);
  try {
    await acquireRootLock(root);
    try {
      return await operation();
    } finally {
      await releaseRootLock(root);
    }
  } finally {
    release();
    if (chains.get(root) === tail) chains.delete(root);
  }
}

export interface ProductForkCreated {
  ok: true;
  /** 新会话（target 的精确来源）。 */
  session: SessionRef;
  /** 新会话文件路径。 */
  eventsPath: string;
  /** 实际被指向的父会话（可能是 source 的某个祖先）。 */
  parent: SessionRef;
  /** 父文件里的物理边界（含）。 */
  boundaryEventId: number;
  totalRounds: number;
}

export type ProductForkResult = ProductForkCreated | { ok: false; error: string };

/** 产品指针分叉（CLI 与桌面共用的唯一创建入口）。
 *  - 轮次在**可见历史**里选，再由 `forkPointInView` 映射到真实来源与物理边界；
 *  - 父日志只读；新会话首行只有 `session_meta.fork`（不复制父事件）；
 *  - 目标排他创建；依赖检查与创建在同一个会话根临界区里完成（并发删除不会留下断链）；
 *  - 目标工作区必须与来源相同（产品分叉不跨项目搬家）。 */
export async function createProductFork(
  source: SessionRef, round: number, target: SessionRef,
  options?: { sessionsRoot?: string },
): Promise<ProductForkResult> {
  let sourceRoot: string;
  let targetRoot: string;
  let workspace: string;
  try {
    const rawSource = options?.sessionsRoot ?? join(await realpath(source.workspace), ".agent", "sessions");
    const rawTarget = options?.sessionsRoot ?? join(await realpath(target.workspace), ".agent", "sessions");
    sourceRoot = await realpath(rawSource);
    targetRoot = await realpath(rawTarget);
    // 来源引用里的 workspace：标准布局从根反推；非标准根（测试/userData）退回调用方给的。
    workspace = workspaceOfSessionsRoot(sourceRoot) ?? source.workspace;
  } catch (error) {
    return { ok: false, error: `会话根不可用：${error instanceof Error ? error.message : String(error)}` };
  }
  if (sourceRoot !== targetRoot) {
    return { ok: false, error: `分叉目标必须在同一会话根（${sourceRoot} ≠ ${targetRoot}）` };
  }
  try {
    return await withSessionMutation(sourceRoot, async (): Promise<ProductForkResult> => {
      if (!(await isSessionInRoot(sourceRoot, source.sessionId))) {
        return { ok: false, error: `源会话不存在：${source.sessionId}` };
      }
      let view;
      try {
        view = await readSessionView({ workspace, sessionId: source.sessionId }, sourceRoot);
      } catch (error) {
        return { ok: false, error: `读源会话失败：${error instanceof Error ? error.message : String(error)}` };
      }
      const point = forkPointInView(view, round);
      if ("error" in point) return { ok: false, error: point.error };
      const targetPath = join(targetRoot, target.sessionId + ".jsonl");
      if (existsSync(targetPath)) return { ok: false, error: `目标会话已存在：${target.sessionId}（不覆盖既有转录）` };
      const parentPath = join(sourceRoot, point.source.sessionId + ".jsonl");
      const scratch = join(targetRoot, ".fork-" + target.sessionId);
      try {
        const made = await forkSessionPointer(parentPath, point.boundaryEventId, scratch, point.source.sessionId);
        await rename(made.eventsPath, targetPath);
        return {
          ok: true,
          session: { workspace, sessionId: target.sessionId },
          eventsPath: targetPath,
          parent: point.source,
          boundaryEventId: point.boundaryEventId,
          totalRounds: point.totalRounds,
        };
      } catch (error) {
        return { ok: false, error: `创建分叉失败：${error instanceof Error ? error.message : String(error)}` };
      } finally {
        await rm(scratch, { recursive: true, force: true }).catch(() => undefined);
      }
    });
  } catch (error) {
    return { ok: false, error: `会话根被占用或不可用：${error instanceof Error ? error.message : String(error)}` };
  }
}
